receipt_format.schema:
{
  "task_id": "<kebab-case identifier>",
  "bot": "<bot-id>",
  "started_at": "<iso8601>",
  "completed_at": "<iso8601>",
  "commands": [
    { "cmd": "<exact command run>", "exit_code": <int>, "duration_s": <float>,
      "output_tail": "<last few lines, for context>" }
  ],
  "claims": [
    { "claim": "<what you assert is true>", "evidence_command_index": <int>,
      "expects_failure": <bool — true only for a reproduction step, where the cited
                          command SHOULD have failed> }
  ],
  "unverified": [ "<what you could not check, and why>" ],
  "files_changed": [ "<repo-relative path>" ],
  "contract_changes": [ "<contract surface touched, or empty>" ],
  "rollback_plan": "<required for deployments, else null>",
  "approvals": [
    { "operation": "<what was approved>", "approved_by": "<human>", "at": "<iso8601>",
      "blast_radius": "<what it affects>" }
  ],
  "approved_by": "<reviewing bot or human — never yourself>"
}

example.shape:
{
  "task_id": "fix-empty-cursor-timeout",
  "bot": "bot-01-systems-backend",
  "commands": [
    { "cmd": "pytest tests/test_cursor.py::test_empty -q", "exit_code": 1, "output_tail": "FAILED" },
    { "cmd": "pytest tests/test_cursor.py::test_empty -q", "exit_code": 0, "output_tail": "1 passed" }
  ],
  "claims": [
    { "claim": "empty cursor timed out before the fix", "evidence_command_index": 0, "expects_failure": true },
    { "claim": "empty cursor test passes after the fix", "evidence_command_index": 1 }
  ],
  "unverified": [ "Not run against the production connection pool (max 100); local Postgres only." ],
  "files_changed": [ "services/api/cursor.py" ],
  "approved_by": "bot-06-quality-security"
}
